import 'package:flutter/material.dart';
import '../app.dart';
import '../models/region_profile.dart';
import '../services/local_store.dart';

class SetupPage extends StatefulWidget {final LocalStore store; const SetupPage({super.key,required this.store}); @override State<SetupPage> createState()=>_SetupPageState();}
class _SetupPageState extends State<SetupPage>{String country='AU';String currency='AUD';
 @override Widget build(BuildContext context){final p=regionProfiles[country]!;return Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),const Icon(Icons.account_balance_wallet_rounded,size:58,color:kNeviroGreen),const SizedBox(height:18),const Text('Welcome to NEVIRO',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900,color:kNeviroDark)),const Text('Money • Budget • Fuel',style:TextStyle(fontSize:17,color:kNeviroMuted)),const SizedBox(height:34),DropdownButtonFormField<String>(initialValue:country,decoration:const InputDecoration(labelText:'Country'),items:regionProfiles.values.map((x)=>DropdownMenuItem(value:x.code,child:Text(x.name))).toList(),onChanged:(v){if(v==null)return;setState((){country=v;currency=regionProfiles[v]!.currencyCode;});}),const SizedBox(height:16),DropdownButtonFormField<String>(initialValue:currency,key:ValueKey(currency),decoration:const InputDecoration(labelText:'Currency'),items:<String>['AUD','LKR','INR','NZD','NPR','SGD'].map((x)=>DropdownMenuItem(value:x,child:Text('$x  ${currencySymbolFor(x)}'))).toList(),onChanged:(v)=>setState(()=>currency=v??p.currencyCode)),const SizedBox(height:12),const Text('You can change these later in Settings.',style:TextStyle(color:kNeviroMuted)),const Spacer(),SizedBox(width:double.infinity,height:54,child:FilledButton(onPressed:()=>widget.store.completeSetup(country,currency),style:FilledButton.styleFrom(backgroundColor:kNeviroGreen),child:const Text('Continue',style:TextStyle(fontWeight:FontWeight.w800)))),const SizedBox(height:12)]))));}}
